\label{definition:HSP}
		Let $\mathcal{X} \subset \mathbb{H}^n$ be a set of vectors and $\mathcal{T}$ a finite set of linear maps $\mathbb{H}^n\to \mathbb{H}^m$. We say that $\mathcal{X}$ and $\mathcal{T}$ satisfy the ``homomorphic sensing property'', denoted by $\operatorname{hsp}(\mathcal{X},\mathcal{T})$, if the following holds:
		\begin{align*}
			\operatorname{hsp}(\mathcal{X},\mathcal{T}):\ \ \forall  v_1,v_2\in\mathcal{X}, \forall \tau_1,\tau_2\in\mathcal{T}, \ \ \tau_1(v_1)=\tau_2(v_2) \Rightarrow v_1=v_2.
		\end{align*}
		If $\tau_1(v_1)=\tau_2(v_2)$ only implies $v_1=\pm v_2$, then we will use the notation $\operatorname{hsp}_\pm(\mathcal{X},\mathcal{T})$.

\label{theorem:HS}
		Suppose $\operatorname{rank}(\tau)\geq 2d$ for every $\tau\in\mathcal{T}$. Then $\operatorname{hsp}(\mathcal{V},\mathcal{T})$ holds true for a generic subspace $\mathcal{V}$ of $\mathbb{H}^n$ of dimension $d$ whenever 
		\begin{align}\label{eq:HS-condition_U}
			d \leq \operatorname{codim}(\mathcal{U}_{\tau_1,\tau_2}),\ \ \ \forall \tau_1,\tau_2\in\mathcal{T}.
		\end{align}

\label{prop:HS-sign}
		Suppose that for every $\tau\in\mathcal{T}$ we have $\operatorname{rank}(\tau)\geq 2d$. Let $\mathcal{U}^\pm_{\tau_1,\tau_2}:=\mathcal{U}_{\tau_1,\tau_2}\backslash \ker(\overline{\tau}_1 +\overline{\tau}_2)$. Then $\operatorname{hsp}_\pm(\mathcal{V},\mathcal{T})$ holds true for a generic subspace $\mathcal{V}$ of $\mathbb{H}^n$ of dimension $d$ whenever 
		\begin{align}\label{eq:HS-condition_U_sign}
			d \le \operatorname{codim}(\mathcal{U}^\pm_{\tau_1,\tau_2}),\ \ \ \forall \tau_1,\tau_2\in\mathcal{T}.                                
		\end{align}

\label{theorem:HS-deterministic-noise}
Let $\mathcal{V}\subset\mathbb{H}^{n}$  be a subspace of dimension $d$ that satisfies $\operatorname{hsp}(\mathcal{V},\mathcal{T})$ and let $V\in\mathbb{H}^{n\times d}$ be a matrix that has $\mathcal{V}$ as its column-space. Let $(\hat{\tau},\hat{v})$ be a solution to \eqref{eq:HS-MLE} with $\hat{T}$ the matrix representation of $\hat{\tau}$. Set $\mathcal{T}_1:=\{\tau\in\mathcal{T}:y\in\tau(\mathcal{V})\}$. If $\mathcal{T} = \mathcal{T}_1$ or 
		\begin{align}\label{eq:deterministic_noise_condition}
			2\|\epsilon\|_{#2}<\|y\|_{#2}\Big(1-\max_{\tau\in\mathcal{T}\backslash\mathcal{T}_1}\cos\big(y,\tau(\mathcal{V})\big)\Big),	
		\end{align} 
		then $\hat{v} - v^*=V(\hat{T} V)^{\dagger}\epsilon$, where $(\hat{T} V)^{\dagger}$ is the pseudoinverse of $\hat{T} V$. In particular $\|\hat{v} - v^*\|_2 \leq \sigma(V(\hat{T} V)^{\dagger}) \|\epsilon\|_2$.

\label{corollary:noise}
	    \vspace{-0.4cm}
		If \eqref{eq:deterministic_noise_condition} holds with $\mathcal{T}=\mathcal{S}_{r,m}$ and if $A$ satisfies $\operatorname{hsp}(\mathbb{R}^n,\mathcal{S}_{r,m}A)$, then $\hat{x}-x^*=(\hat{T} A)^{\dagger}\epsilon$.

\label{prop:E>n-d}
		In addition to the hypotheses of Theorem \ref{theorem:HS}, 
		suppose $\dim(\mathscr{E}_{(\tau_1,\tau_2),1})=n-d_0>n-d$. There are two subspaces $\mathcal{V}_0^* \subset \mathcal{V}^*$ of $\mathbb{H}^n$ of dimension $d_0$ and $d$ respectively so that $\dim(\tau_1(\mathcal{V}_0^*)+\tau_2(\mathcal{V}^*))=d_0+d$.

We have
		\begin{align*}
			[\dim(\mathcal{R}_{\beta})-(n-d)]+\dim(\ker(\tau_1))=\dim(\mathcal{R}_\beta)+(d-\operatorname{rank}(\tau_1))\le \dim(\mathcal{R}_\beta)
		\end{align*}
		and a similar inequality for $\tau_2$. Moreover, 
		\begin{align*}
			[\dim(\mathcal{R}_{\beta})-(n-d)]+ \dim(\mathcal{R}_\beta\cap\mathcal{F}_\beta)\leq \dim(\mathcal{R}_{\beta})+ [\dim(\mathcal{R}_{\beta}\cap\mathcal{F}_{\beta})-(n-d)]\leq \dim(\mathcal{R}_{\beta}).
		\end{align*}
		Consequently, by Lemma \ref{lemma:subspaces_intersect_subspace} there exists a subspace $\mathcal{W}_\beta$ of $\mathcal{R}_\beta$ of dimension $[\dim(\mathcal{R}_{\beta})-(n-d)]$ which does not intersect $\ker(\tau_1), \ker(\tau_2)$ and $\mathcal{R}_\beta\cap\mathcal{F}_\beta$. Clearly $\beta >0$ and Lemma \ref{lemma:chain-property} gives $\tau_1(\mathcal{W}_\beta)\subset\tau_1(\mathcal{R}_\beta)=\mathcal{G}_\beta$. Recalling definition  \eqref{eq:def-RFG}, we have
			\begin{align*}
			\mathcal{W}_\beta\cap \tau_2^{-1}(\tau_1(\mathcal{W}_\beta))&\subset \mathcal{W}_\beta\cap \tau_2^{-1}(\mathcal{G}_\beta)\\
			&=\mathcal{W}_\beta\cap \tau_2^{-1}(\mathcal{G}_\beta)\cap\mathcal{R}_\beta\\
			&=\mathcal{W}_\beta\cap \tau_2^{-1}(\mathcal{G}_\beta)\cap\tau_1^{-1}(\mathcal{G}_\beta)\cap\mathcal{R}_{\beta-1}\cap\mathcal{F}_{\beta-1}\\
			&=\mathcal{W}_\beta\cap \tau_1^{-1}(\mathcal{G}_\beta)\cap\mathcal{F}_\beta\\
			&\subset\mathcal{W}_\beta\cap\mathcal{F}_\beta=\mathcal{W}_\beta\cap\mathcal{R}_\beta\cap\mathcal{F}_\beta=0.
		\end{align*}
		In short $\mathcal{W}_\beta\cap \tau_2^{-1}(\tau_1(\mathcal{W}_\beta))=0$, and it follows that $\tau_2(\mathcal{W}_\beta)\cap\tau_1(\mathcal{W}_\beta)=0$. Recalling that $\mathcal{W}_\beta\cap\ker(\tau_1)=0$ and $\mathcal{W}_\beta\cap\ker(\tau_2)=0$, we conclude that $\dim(\tau_1(\mathcal{W}_\beta)+\tau_2(\mathcal{W}_\beta))=2\dim(\mathcal{W}_\beta)$. \qed

We have 
\begin{align*}
[\dim(\mathcal{R}_{\gamma}\cap\mathcal{F}_{\gamma})-(n-d)]+\dim(\ker(\tau_1))=\dim(\mathcal{R}_{\gamma}\cap\mathcal{F}_{\gamma})+(d-\operatorname{rank}(\tau_1))\le\dim(\mathcal{R}_{\gamma}\cap\mathcal{F}_{\gamma})
\end{align*} and a similar inequality for $\tau_2$. Moreover, 
		\begin{align*}
	    	[\dim(\mathcal{R}_{\gamma}\cap\mathcal{F}_{\gamma})-(n-d)]+\dim(\mathcal{R}_{\gamma+1})=\dim(\mathcal{R}_{\gamma}\cap\mathcal{F}_{\gamma})+[\dim(\mathcal{R}_{\gamma+1})- (n-d)]\leq \dim(\mathcal{R}_{\gamma}\cap\mathcal{F}_{\gamma}).
		\end{align*} Thus Lemma \ref{lemma:subspaces_intersect_subspace} implies the existence of a subspace $\mathcal{Z}_\gamma$ of $\mathcal{R}_{\gamma}\cap\mathcal{F}_{\gamma}$ of dimension $[\dim(\mathcal{R}_{\gamma}\cap\mathcal{F}_{\gamma})-(n-d)]$ which does not intersect $\ker(\tau_1), \ker(\tau_2)$ and $\mathcal{R}_{\gamma+1}$. This gives $\dim(\tau_1(\mathcal{Z}_\gamma))=\dim(\tau_2(\mathcal{Z}_\gamma))=\dim(\mathcal{Z}_\gamma)$. It now suffices to prove $\tau_1(\mathcal{Z}_\gamma)\cap\tau_2(\mathcal{Z}_\gamma)=0$. Let $\tau_1(v_1)=\tau_2(v_2)$ for some $v_1,v_2\in \mathcal{Z}_\gamma$. Then		\begin{align*}
			\tau_1(v_1)\in \tau_1(\mathcal{R}_\gamma\cap\mathcal{F}_\gamma)\cap\tau_2(\mathcal{R}_\gamma\cap\mathcal{F}_\gamma)=:\mathcal{G}_{\gamma+1}.
		\end{align*}
		This implies $v_1\in\tau_1^{-1}(\mathcal{G}_{\gamma+1})$ and so
		\begin{align*}
			v_1\in \mathcal{Z}_\gamma\cap\tau_1^{-1}(\mathcal{G}_{\gamma+1})=\mathcal{Z}_\gamma\cap\tau_1^{-1}(\mathcal{G}_{\gamma+1})\cap \mathcal{R}_\gamma\cap\mathcal{F}_\gamma=\mathcal{Z}_\gamma \cap \mathcal{R}_{\gamma+1}=0.
		\end{align*} Thus $v_1=0$ and we have proved $\tau_1(\mathcal{Z}_\gamma)\cap\tau_2(\mathcal{Z}_\gamma)=0$.  \qed

\label{lemma:enlarge_RcapF_Z->R_W}
		In addition to the hypotheses of Proposition \ref{prop:E<=n-d}, suppose for some $j$ that $\dim(\mathcal{R}_{j}\cap\mathcal{F}_{j})> n-d$ and that there exists a subspace $\mathcal{Z}_j$ of $\mathcal{R}_j\cap\mathcal{F}_j$ satisfying
		\begin{align*}
			\mathscr{P}(\mathcal{Z}_j):\ \dim(\mathcal{Z}_j)=[\dim(\mathcal{R}_{j}\cap\mathcal{F}_{j})-(n-d)] \text{\ \ and \ } \dim(\tau_1(\mathcal{Z}_j)+\tau_2(\mathcal{Z}_j))=2\dim(\mathcal{Z}_j).
		\end{align*}
		Then there exists a subspace $\mathcal{W}_j$ of $\mathcal{R}_{j}$ satisfying $\mathcal{Z}_j\subset \mathcal{W}_j$ and
		\begin{align*}
			\mathscr{P}(\mathcal{W}_j):\ \dim(\mathcal{W}_j)=[\dim(\mathcal{R}_{j})-(n-d)] \text{\ \ and \ } \dim(\tau_1(\mathcal{W}_j)+\tau_2(\mathcal{W}_j))=2\dim(\mathcal{W}_j).
		\end{align*}

If $\mathcal{R}_j\cap\mathcal{F}_j=\mathcal{R}_j$, then we are done by letting $\mathcal{W}_j=\mathcal{Z}_j$. In what follows we assume $\dim(\mathcal{R}_j)>\dim(\mathcal{R}_j\cap\mathcal{F}_j)$, in particular $j > 0$. The subspace $\tau_1^{-1}(\tau_1(\mathcal{Z}_j)+\tau_2(\mathcal{Z}_j))$ has dimension at most $(n-\operatorname{rank}(\tau_1))+2[\dim(\mathcal{R}_j\cap\mathcal{F}_j)-(n-d)]$. Hence 
			\begin{align*}
			[\dim(\mathcal{R}_j)-\dim(\mathcal{R}_j\cap\mathcal{F}_j)]+\dim(\tau_1^{-1}(\tau_1(\mathcal{Z}_j)+\tau_2(\mathcal{Z}_j)))&\le \dim(\mathcal{R}_j)+[2d-\operatorname{rank}(\tau_1)]+[\dim(\mathcal{R}_j\cap\mathcal{F}_j)-n] \nonumber \\
			&\leq \dim(\mathcal{R}_j).
		\end{align*} By hypothesis it is also true that $[\dim(\mathcal{R}_j)-\dim(\mathcal{R}_j\cap\mathcal{F}_j)]+\dim(\ker(\tau_1)) \le \dim(\mathcal{R}_j)$ and similarly for $\tau_2$. Hence, by Lemma \ref{lemma:subspaces_intersect_subspace} there is a subspace $\mathcal{W}_j'$ of $\mathcal{R}_j$ of dimension $[\dim(\mathcal{R}_j)-\dim(\mathcal{R}_j\cap\mathcal{F}_j)]$, which does not intersect the subspaces $\mathcal{R}_j\cap\mathcal{F}_j, \, \tau_1^{-1}(\tau_1(\mathcal{Z}_j)+\tau_2(\mathcal{Z}_j)), \, \ker(\tau_1), \, \ker(\tau_2)$. In particular $\tau_1(\mathcal{W}_j')\cap[\tau_1(\mathcal{Z}_j)+\tau_2(\mathcal{Z}_j)]=0$. This together with the hypothesis gives $\dim (\tau_1(\mathcal{Z}_j)+\tau_2(\mathcal{Z}_j)+\tau_1(\mathcal{W}_j')) = 2[\dim(\mathcal{R}_{j}\cap\mathcal{F}_{j})-(n-d)]+[\dim(\mathcal{R}_j)-\dim(\mathcal{R}_j\cap\mathcal{F}_j)]$. Equivalently,
		\begin{align}\label{eq:Zj+Wj'_Zj}
			\dim(\tau_1(\mathcal{Z}_j+\mathcal{W}_j')+\tau_2(\mathcal{Z}_j))=\dim(\mathcal{R}_{j})+\dim(\mathcal{R}_{j}\cap\mathcal{F}_{j})-2(n-d).
		\end{align}
		Since $\mathcal{Z}_j\subset \mathcal{R}_j\cap\mathcal{F}_j$ we see that $\tau_2(\mathcal{Z}_j)\subset \tau_2(\mathcal{F}_j)=\mathcal{G}_j$. With $\tau_1(\mathcal{Z}_j+\mathcal{W}_j')\subset \tau_1(\mathcal{R}_j)=\mathcal{G}_j$ (Lemma \ref{lemma:chain-property}), we obtain that $\tau_1(\mathcal{Z}_j+\mathcal{W}_j')+\tau_2(\mathcal{Z}_j)$ is a subspace of $\mathcal{G}_j$, and consequently
		\begin{align*}
			\mathcal{W}_j'\cap\tau_2^{-1}(\tau_1(\mathcal{Z}_j+\mathcal{W}_j')+\tau_2(\mathcal{Z}_j))&\subset \mathcal{W}_j'\cap\tau_2^{-1}(\mathcal{G}_j)\\
			&=\mathcal{W}_j'\cap\tau_2^{-1}(\mathcal{G}_j) \cap\mathcal{R}_j\\
			&=\mathcal{W}_j'\cap\tau_2^{-1}(\mathcal{G}_j) \cap\tau_1^{-1}(\mathcal{G}_j) \cap\mathcal{R}_{j-1}\cap\mathcal{F}_{j-1}\\
			&=\mathcal{W}_j'\cap \tau_1^{-1}(\mathcal{G}_j)\cap\mathcal{F}_j\\
			&\subset \mathcal{W}_j'\cap\mathcal{F}_j\\
			&=\mathcal{W}_j'\cap\mathcal{F}_j\cap\mathcal{R}_j=0. 
		\end{align*}
In short, we have $\mathcal{W}_j'\cap\tau_2^{-1}(\tau_1(\mathcal{Z}_j+\mathcal{W}_j')+\tau_2(\mathcal{Z}_j))=0$ and so $\tau_2(\mathcal{W}_j')\cap[\tau_1(\mathcal{Z}_j+\mathcal{W}_j')+\tau_2(\mathcal{Z}_j)]=0$. Recalling \eqref{eq:Zj+Wj'_Zj}, it follows that $[\tau_1(\mathcal{Z}_j+\mathcal{W}_j')+\tau_2(\mathcal{Z}_j)]+\tau_2(\mathcal{W}_j')$ is of dimension $[\dim(\mathcal{R}_{j})+\dim(\mathcal{R}_{j}\cap\mathcal{F}_{j})-2(n-d)]+ [\dim(\mathcal{R}_j)-\dim(\mathcal{R}_j\cap\mathcal{F}_j)]$, that is,
		\begin{align*}
			\dim(\tau_1(\mathcal{Z}_j+\mathcal{W}_j')+\tau_2(\mathcal{Z}_j+\mathcal{W}_j'))=2\dim(\mathcal{R}_{j})-2(n-d).
		\end{align*}
		By letting $\mathcal{W}_j=\mathcal{Z}_j+\mathcal{W}_j'$ we finished the proof. \qed

\label{lemma:enlarge_R_W->RcapF_Z}
		In addition to the hypotheses of Proposition \ref{prop:E<=n-d}, suppose for some $j$ that $\dim(\mathcal{R}_{j+1})> n-d$ and that there exists a subspace $\mathcal{W}_{j+1}$ of $\mathcal{R}_{j+1}$ satisfying 
		\begin{align*}
			\mathscr{P}(\mathcal{W}_{j+1}):\ \dim(\mathcal{W}_{j+1})=[\dim(\mathcal{R}_{j+1})-(n-d)] \text{\ \ and \ } \dim(\tau_1(\mathcal{W}_{j+1})+\tau_2(\mathcal{W}_{j+1}))=2\dim(\mathcal{W}_{j+1}).
		\end{align*}
		Then there exists a subspace $\mathcal{Z}_j$ of $\mathcal{R}_{j}\cap\mathcal{F}_{j}$ satisfying $\mathcal{W}_{j+1}\subset \mathcal{Z}_j$ and 
		\begin{align*}
			\mathscr{P}(\mathcal{Z}_j):\ \dim(\mathcal{Z}_j)=[\dim(\mathcal{R}_{j}\cap\mathcal{F}_{j})-(n-d)] \text{\ \ and \ } \dim(\tau_1(\mathcal{Z}_j)+\tau_2(\mathcal{Z}_j))=2\dim(\mathcal{Z}_j).
		\end{align*} \qed
